<?php
if(!defined('ABSPATH')){exit;}
final class AICS_Automation_SEO_Service{public function __construct(private ?AICS_Article_Repository $articles=null,private ?AICS_SEO_Workflow_Service $workflow=null){$this->articles=$articles??new AICS_Article_Repository();$this->workflow=$workflow??new AICS_SEO_Workflow_Service($this->articles);}public function process_one(array $run,array $configuration,string $phase):array{$settings=AICS_SEO_Configuration::normalize_stored($configuration['seo_settings']??array(),false);if(!$settings['enabled']){return array('success'=>true,'complete'=>true,'code'=>'seo_disabled');}$articles=$this->articles->get_articles_for_run(absint($run['id']),array('profile_id'=>absint($run['profile_id']),'limit'=>100,'orderby'=>'created_at','order'=>'ASC'));foreach($articles as $a){if('rejected'===$a['status']){continue;}if('generate'===$phase&&!in_array($a['seo_status'],array('generated','review_required','approved','applied'),true)){$r=$this->workflow->generate($a['id'],$settings,array());$r['complete']=false;return $r;}if('apply'===$phase&&'applied'!==$a['seo_status']){$r=$this->workflow->apply($a['id'],$settings,0);$r['complete']=false;return $r;}}return array('success'=>true,'complete'=>true,'code'=>'generate'===$phase?'seo_generation_complete':'seo_application_complete');}}
